const cfg = $input.first().json;
const inp = $('When Executed by Another Workflow').first().json;

if (!cfg || !cfg.model) throw new Error(`No obs.profiles row for profile '${inp.profile}'`);
if (!cfg.body)          throw new Error(`No ACTIVE obs.prompts row named '${inp.prompt_name}'`);

const vars = JSON.parse(inp.vars_json || '{}');

// An unresolved placeholder reaching the model is silent nonsense, so fail loudly.
const body = cfg.body.replace(/\{\{(\w+)\}\}/g, (_m, k) => {
  if (!(k in vars)) throw new Error(`Prompt '${inp.prompt_name}' needs {{${k}}}, not supplied`);

  let value = vars[k];

  // 1. If it arrives as a string but looks like an escaped or embedded JSON string
  if (typeof value === 'string' && (value.trim().startsWith('{') || value.includes('\\"'))) {
    try {
      // Unpack recursively until we get a real JavaScript object/array
      while (typeof value === 'string') {
        value = JSON.parse(value);
      }
    } catch (e) {
      // Fallback to the original raw string if parsing fails
      value = vars[k];
    }
  }

  // 2. Format object data if it resolved to a clean object/array
  if (typeof value === 'object' && value !== null) {
    if (Array.isArray(value)) {
      // Filter out empty arrays or invalid entries
      const cleanArray = value.filter(item => item !== null && item !== undefined && String(item).trim() !== '');
      return cleanArray.length > 0 ? cleanArray.join(', ') : 'none';
    } else {
      // Convert objects (like sensory data) to a clean string, skipping null/undefined/empty fields
      return Object.entries(value)
        .filter(([_, val]) => {
          if (val === null || val === undefined) return false;
          if (Array.isArray(val) && val.length === 0) return false;
          if (typeof val === 'string' && val.trim() === '') return false;
          return true;
        })
        .map(([key, val]) => {
          const valString = Array.isArray(val) ? val.join(', ') : String(val);
          return `${key}: [${valString}]`;
        })
        .join(' | ') || 'none'; // Fallback to 'none' if the entire object ends up empty
    }
  }

  // 3. Fallback for primitive values (strings, numbers, booleans)
  if (value === null || value === undefined || String(value).trim() === '') {
    return 'none';
  }

  return String(value);
});


const schemaRaw = String(inp.schema_json || '').trim();

const payload = {
  model: cfg.model,
  messages: [{ role: 'user', content: body }],
  options: typeof cfg.options === 'string' ? JSON.parse(cfg.options) : (cfg.options || {}),
  stream: false,
  // ⛔ gemma4 reasons by default, and the reasoning is billed against the SAME
  // generation budget as the answer. Measured run 65: `compose` with
  // num_predict 900 spent all 900 tokens thinking and returned message.content
  // EMPTY -- done_reason "length", nothing to show the brewer. The stray
  // "thought" and "<channel|>" fragments in earlier answers were the same thing
  // leaking through. Steps here want the answer, never the deliberation.
  think: false,
};
if (schemaRaw) payload.format = JSON.parse(schemaRaw);

return [{ json: {
  payload,
  model: cfg.model,
  sha256: cfg.sha256,
  started: Date.now(),
  rendered_chars: body.length,
}}];

const res = $input.first().json;
const r   = $('Render prompt').first().json;
const inp = $('When Executed by Another Workflow').first().json;

const psRaw = $('Check residency').first().json;
const loadedModels = (psRaw?.models ?? []).map(m => m.name ?? m.model);
const wasLoaded = loadedModels.includes(r.model);

const text = res?.message?.content;
if (typeof text !== 'string' || !text.trim()) {
  throw new Error(`Ollama returned no content for step '${inp.step_id}': ${JSON.stringify(res).slice(0, 400)}`);
}

const schemaRaw = String(inp.schema_json || '').trim();
let output = text, verdict = 'ok';

if (schemaRaw) {
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    throw new Error(`Step '${inp.step_id}' was asked for JSON and returned prose: ${text.slice(0, 300)}`);
  }
  const required = JSON.parse(schemaRaw).required ?? [];
  const missing = required.filter(k => !(k in parsed));
  if (missing.length) {
    throw new Error(`Step '${inp.step_id}' output missing required key(s): ${missing.join(', ')}`);
  }
  output = parsed;
  verdict = 'schema_ok';
}

return [{ json: {
  run_id: inp.run_id,
  seq: inp.seq,
  step_id: inp.step_id,
  profile: inp.profile,
  model: r.model,
  model_loaded: wasLoaded,
  prompt_sha256: r.sha256,
  output,
  verdict,
  tokens_in: res.prompt_eval_count ?? null,
  tokens_out: res.eval_count ?? null,
  latency_ms: Date.now() - r.started,
}}];

const v = $('Validate output').first().json;
return [{ json: {
  output: v.output,
  prompt_sha256: v.prompt_sha256,
  model: v.model,
  model_loaded: v.model_loaded,
  latency_ms: v.latency_ms,
  tokens_in: v.tokens_in,
  tokens_out: v.tokens_out,
}}];

